from datetime import datetime
from pathlib import Path
import sqlite3

import pandas as pd

import config
import models


SCHEMA = """
CREATE TABLE IF NOT EXISTS directions (
    id          INTEGER PRIMARY KEY,
    key         TEXT NOT NULL UNIQUE,          -- 'sports' | 'leisure' | 'career'
    name        TEXT NOT NULL,
    sort_order  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS bundles (
    id            INTEGER PRIMARY KEY,
    key           TEXT NOT NULL UNIQUE,        -- e.g. 'sports_racket'
    direction_id  INTEGER NOT NULL REFERENCES directions(id),
    name          TEXT NOT NULL,
    is_other      INTEGER NOT NULL DEFAULT 0,
    sort_order    INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS clubs (
    id             INTEGER PRIMARY KEY,
    name           TEXT NOT NULL UNIQUE,
    club_category  TEXT,                       -- UniClubs category, e.g. 'Business'
    url            TEXT
);

CREATE TABLE IF NOT EXISTS series (
    id                INTEGER PRIMARY KEY,
    source            TEXT NOT NULL CHECK (source IN ('unisport', 'uniclubs', 'city')),
    external_id       TEXT NOT NULL,
    title             TEXT NOT NULL,
    description       TEXT NOT NULL DEFAULT '',
    organizer         TEXT NOT NULL DEFAULT '',
    club_id           INTEGER REFERENCES clubs(id),
    bundle_id         INTEGER NOT NULL REFERENCES bundles(id),
    event_type        TEXT NOT NULL DEFAULT '',
    sport             TEXT NOT NULL DEFAULT '',       -- Unisport only
    level             TEXT NOT NULL DEFAULT '',       -- Unisport only
    location          TEXT NOT NULL DEFAULT '',
    location_type     TEXT NOT NULL
                      CHECK (location_type IN ('st_gallen', 'online', 'elsewhere', 'tba')),
    source_url        TEXT NOT NULL DEFAULT '',
    registration_url  TEXT NOT NULL DEFAULT '',
    price_rappen      INTEGER,                        -- NULL = unknown, 0 = free
    members_only      INTEGER NOT NULL DEFAULT 0,
    is_recurring      INTEGER NOT NULL DEFAULT 0,
    is_placeholder    INTEGER NOT NULL DEFAULT 0,     -- 1 = synthetic placeholder data
    UNIQUE (source, external_id)
);

CREATE TABLE IF NOT EXISTS events (
    id                INTEGER PRIMARY KEY,
    series_id         INTEGER NOT NULL REFERENCES series(id),
    start_time        TEXT NOT NULL,                  -- 'YYYY-MM-DD HH:MM:SS', Europe/Zurich
    end_time          TEXT NOT NULL,
    end_is_estimated  INTEGER NOT NULL DEFAULT 0,
    status            TEXT NOT NULL DEFAULT 'open'
                      CHECK (status IN
                             ('open', 'apply', 'members_only', 'ongoing', 'full', 'closed')),
    UNIQUE (series_id, start_time)
);

CREATE TABLE IF NOT EXISTS users (
    id              INTEGER PRIMARY KEY,
    display_name    TEXT NOT NULL,
    friend_code     TEXT NOT NULL UNIQUE,
    is_synthetic    INTEGER NOT NULL DEFAULT 1,
    sharing_opt_in  INTEGER NOT NULL DEFAULT 0,
    created_at      TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS user_directions (
    id            INTEGER PRIMARY KEY,
    user_id       INTEGER NOT NULL REFERENCES users(id),
    direction_id  INTEGER NOT NULL REFERENCES directions(id),
    UNIQUE (user_id, direction_id)
);

-- One table for three kinds of favorites. target_id points to series.id, clubs.id or
-- bundles.id depending on kind, so SQLite cannot enforce it as a foreign key:
-- add_favorite() checks that the target exists before inserting.  [DEFAULT D-21]
CREATE TABLE IF NOT EXISTS favorites (
    id          INTEGER PRIMARY KEY,
    user_id     INTEGER NOT NULL REFERENCES users(id),
    kind        TEXT NOT NULL CHECK (kind IN ('series', 'club', 'bundle')),
    target_id   INTEGER NOT NULL,
    created_at  TEXT NOT NULL,
    UNIQUE (user_id, kind, target_id)
);

CREATE TABLE IF NOT EXISTS interactions (
    id            INTEGER PRIMARY KEY,
    user_id       INTEGER NOT NULL REFERENCES users(id),
    event_id      INTEGER NOT NULL REFERENCES events(id),
    status        TEXT NOT NULL
                  CHECK (status IN ('confirmed', 'cancelled', 'attended', 'not_attended')),
    rating        INTEGER CHECK (rating BETWEEN 1 AND 5),
    confirmed_at  TEXT NOT NULL,
    answered_at   TEXT,
    is_demo       INTEGER NOT NULL DEFAULT 0,   -- 1 = local user's demo history [DEFAULT D-25]
    UNIQUE (user_id, event_id),
    CHECK (rating IS NULL OR status = 'attended')
);

CREATE TABLE IF NOT EXISTS friendships (
    id          INTEGER PRIMARY KEY,
    user_id     INTEGER NOT NULL REFERENCES users(id),
    friend_id   INTEGER NOT NULL REFERENCES users(id),
    created_at  TEXT NOT NULL,
    UNIQUE (user_id, friend_id),
    CHECK (user_id <> friend_id)
);

CREATE TABLE IF NOT EXISTS invitations (
    id            INTEGER PRIMARY KEY,
    sender_id     INTEGER NOT NULL REFERENCES users(id),
    recipient_id  INTEGER NOT NULL REFERENCES users(id),
    event_id      INTEGER NOT NULL REFERENCES events(id),
    status        TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'accepted', 'declined')),
    is_simulated  INTEGER NOT NULL DEFAULT 0,
    created_at    TEXT NOT NULL,
    answered_at   TEXT,
    UNIQUE (sender_id, recipient_id, event_id)
);

CREATE TABLE IF NOT EXISTS app_settings (
    id     INTEGER PRIMARY KEY,
    key    TEXT NOT NULL UNIQUE,
    value  TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS import_log (
    id           INTEGER PRIMARY KEY,
    source       TEXT NOT NULL,
    started_at   TEXT NOT NULL,
    origin       TEXT NOT NULL CHECK (origin IN ('live', 'snapshot', 'placeholder', 'excel')),
    n_series     INTEGER NOT NULL DEFAULT 0,
    n_events     INTEGER NOT NULL DEFAULT 0,
    outcome      TEXT NOT NULL CHECK (outcome IN ('ok', 'failed', 'rejected')),
    message      TEXT NOT NULL DEFAULT ''
);
"""


EVENTS_IN_RANGE_SQL = '''
SELECT e.id, e.series_id, e.start_time, e.end_time, e.end_is_estimated, e.status,
        s.source, s.title, s.description, s.organizer, s.event_type, s.sport, s.level,
        s.location, s.location_type, s.source_url, s.registration_url, s.price_rappen,
        s.members_only, s.is_recurring, s.club_id, c.name AS club_name, c.club_category,
        b.key AS bundle_key, b.name AS bundle_name, d.key AS direction_key
 FROM events e JOIN series s ON s.id=e.series_id
 JOIN bundles b ON b.id=s.bundle_id JOIN directions d ON d.id=b.direction_id
 LEFT JOIN clubs c ON c.id=s.club_id
 WHERE e.start_time>=? AND e.start_time<? ORDER BY e.start_time
'''

EVENT_BY_ID_SQL = '''
SELECT e.id, e.series_id, e.start_time, e.end_time, e.end_is_estimated, e.status,
        s.source, s.title, s.description, s.organizer, s.event_type, s.sport, s.level,
        s.location, s.location_type, s.source_url, s.registration_url, s.price_rappen,
        s.members_only, s.is_recurring, s.club_id, c.name AS club_name, c.club_category,
        b.key AS bundle_key, b.name AS bundle_name, d.key AS direction_key
 FROM events e JOIN series s ON s.id=e.series_id
 JOIN bundles b ON b.id=s.bundle_id JOIN directions d ON d.id=b.direction_id
 LEFT JOIN clubs c ON c.id=s.club_id
 WHERE e.id=?
'''

CONFIRMED_EVENTS_SQL = '''
SELECT e.id, e.series_id, e.start_time, e.end_time, e.end_is_estimated, e.status,
        s.source, s.title, s.description, s.organizer, s.event_type, s.sport, s.level,
        s.location, s.location_type, s.source_url, s.registration_url, s.price_rappen,
        s.members_only, s.is_recurring, s.club_id, c.name AS club_name, c.club_category,
        b.key AS bundle_key, b.name AS bundle_name, d.key AS direction_key
 FROM events e JOIN series s ON s.id=e.series_id
 JOIN bundles b ON b.id=s.bundle_id JOIN directions d ON d.id=b.direction_id
 LEFT JOIN clubs c ON c.id=s.club_id
 JOIN interactions i ON i.event_id=e.id
 WHERE i.user_id=? AND i.status='confirmed' AND e.start_time<? AND e.end_time>?
 ORDER BY e.start_time
'''


def get_connection(db_file=config.DB_FILE):
    """Open SQLite with foreign keys; ':memory:' gives tests an isolated database."""
    if str(db_file) != ':memory:':
        Path(db_file).parent.mkdir(parents=True, exist_ok=True)
    # Streamlit may reuse the local connection on another rerun thread (SPEC section 6).
    connection = sqlite3.connect(db_file, timeout=config.DB_TIMEOUT_SECONDS,
                                 check_same_thread=False)
    connection.row_factory = sqlite3.Row
    # Course: A07 – foreign-key enforcement is enabled per connection.
    connection.execute('PRAGMA foreign_keys = 1')
    return connection


def init_db(connection):
    """Create the complete specification schema without disturbing existing rows."""
    with connection:
        for statement in SCHEMA.split(';'):
            if statement.strip():
                connection.execute(statement)


def to_db_text(dt):
    """Serialize a naive local datetime using the shared format."""
    if not isinstance(dt, datetime) or dt.tzinfo is not None:
        raise ValueError('Database time must be a naive local datetime.')
    return dt.strftime(config.DB_TIME_FORMAT)


def from_db_text(text):
    """Parse the shared SQLite timestamp representation."""
    return datetime.strptime(text, config.DB_TIME_FORMAT)


def get_setting(connection, key, default=None):
    """Read one non-secret setting with a default for an absent key."""
    row = connection.execute('SELECT value FROM app_settings WHERE key=?', (key,)).fetchone()
    return row['value'] if row is not None else default


def set_setting(connection, key, value):
    """Upsert one non-secret setting using a bound parameter tuple."""
    with connection:
        connection.execute('''INSERT INTO app_settings (key,value) VALUES (?,?)
            ON CONFLICT(key) DO UPDATE SET value=excluded.value''', (key, str(value)))


def seed_taxonomy(connection, taxonomy):
    """Upsert taxonomy metadata while preserving referenced IDs."""
    with connection:
        for row in taxonomy['directions']:
            connection.execute('''INSERT INTO directions (key,name,sort_order) VALUES (?,?,?)
                ON CONFLICT(key) DO UPDATE SET name=excluded.name, sort_order=excluded.sort_order
            ''', (row['key'], row['name'], row['sort_order']))
        for row in taxonomy['bundles']:
            direction = connection.execute('SELECT id FROM directions WHERE key=?',
                                           (row['direction'],)).fetchone()
            connection.execute('''INSERT INTO bundles (key,direction_id,name,is_other,sort_order)
                VALUES (?,?,?,?,?) ON CONFLICT(key) DO UPDATE SET name=excluded.name,
                is_other=excluded.is_other, sort_order=excluded.sort_order''',
                (row['key'], direction['id'], row['name'], int(row['is_other']), row['sort_order']))
    set_setting(connection, 'taxonomy_version', taxonomy['_meta']['version'])


def _upsert_club(connection, name, club_category='', url=''):
    """Upsert one club inside the caller's transaction."""
    if not name:
        return None
    connection.execute('''INSERT INTO clubs (name,club_category,url) VALUES (?,?,?)
        ON CONFLICT(name) DO UPDATE SET club_category=excluded.club_category,url=excluded.url
    ''', (name, club_category, url))
    return connection.execute('SELECT id FROM clubs WHERE name=?', (name,)).fetchone()['id']


def upsert_club(connection, name, club_category='', url=''):
    """Store a club and return its stable ID."""
    with connection:
        return _upsert_club(connection, name, club_category, url)


def _upsert_series(connection, record, bundle_id, club_id):
    """Upsert an activity's canonical fields inside the caller's transaction."""
    values = [record.get(field, '') for field in config.SERIES_RECORD_FIELDS]
    values.extend([club_id, bundle_id, models.price_to_rappen(record.get('price')),
                   int(record.get('members_only', False)), int(record.get('is_recurring', False)),
                   int(record.get('is_placeholder', False))])
    connection.execute('''INSERT INTO series
        (source,external_id,title,description,organizer,event_type,sport,level,location,
         location_type,source_url,registration_url,club_id,bundle_id,price_rappen,
         members_only,is_recurring,is_placeholder) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        ON CONFLICT(source,external_id) DO UPDATE SET title=excluded.title,
        description=excluded.description,organizer=excluded.organizer,
        event_type=excluded.event_type,
        sport=excluded.sport,level=excluded.level,location=excluded.location,
        location_type=excluded.location_type,source_url=excluded.source_url,
        registration_url=excluded.registration_url,club_id=excluded.club_id,
        bundle_id=excluded.bundle_id,
        price_rappen=excluded.price_rappen,members_only=excluded.members_only,
        is_recurring=excluded.is_recurring,is_placeholder=excluded.is_placeholder
    ''', tuple(values))
    return connection.execute('SELECT id FROM series WHERE source=? AND external_id=?',
                              (record['source'], record['external_id'])).fetchone()['id']


def upsert_series(connection, record, bundle_id, club_id=None):
    """Store one activity by its source/external-ID natural key."""
    with connection:
        return _upsert_series(connection, record, bundle_id, club_id)


def _upsert_event(connection, series_id, start, end, end_is_estimated, status):
    """Upsert one dated occurrence without replacing its identity."""
    connection.execute('''INSERT INTO events
        (series_id,start_time,end_time,end_is_estimated,status) VALUES (?,?,?,?,?)
        ON CONFLICT(series_id,start_time) DO UPDATE SET end_time=excluded.end_time,
        end_is_estimated=excluded.end_is_estimated,status=excluded.status
    ''', (series_id, to_db_text(start), to_db_text(end), int(end_is_estimated), status))
    return connection.execute('SELECT id FROM events WHERE series_id=? AND start_time=?',
                              (series_id, to_db_text(start))).fetchone()['id']


def upsert_event(connection, series_id, start, end, end_is_estimated=False, status='open'):
    """Store one valid occurrence with transactional foreign-key enforcement."""
    if end <= start or status not in config.EVENT_STATUSES:
        raise ValueError('Invalid event interval or status.')
    with connection:
        return _upsert_event(connection, series_id, start, end, end_is_estimated, status)


def apply_source_records(connection, records, source, reconcile=False, now=None):
    """Commit a validated batch atomically and return distinct series/occurrence counts."""
    series_ids, event_ids = set(), set()
    with connection:
        for record in records:
            bundle = connection.execute('SELECT id FROM bundles WHERE key=?',
                                        (record['bundle_key'],)).fetchone()
            if bundle is None:
                raise ValueError('Unknown bundle in source batch.')
            club_id = _upsert_club(connection, record.get('club_name', ''),
                                   record.get('club_category', ''))
            series_id = _upsert_series(connection, record, bundle['id'], club_id)
            event_id = _upsert_event(connection, series_id, record['start'], record['end'],
                                     record['end_is_estimated'], record['status'])
            series_ids.add(series_id)
            event_ids.add(event_id)
        if reconcile:
            _delete_missing_future(connection, source, event_ids, config.local_now(now))
    return len(series_ids), len(event_ids)


def _delete_missing_future(connection, source, retained_ids, now):
    """Delete absent future events only when no interaction or invitation refers to them."""
    rows = connection.execute('''SELECT e.id FROM events e JOIN series s ON s.id=e.series_id
        WHERE s.source=? AND e.start_time>?
        AND NOT EXISTS (SELECT 1 FROM interactions WHERE event_id=e.id)
        AND NOT EXISTS (SELECT 1 FROM invitations WHERE event_id=e.id)
    ''', (source, to_db_text(now))).fetchall()
    for row in rows:
        if row['id'] not in retained_ids:
            connection.execute('DELETE FROM events WHERE id=?', (row['id'],))


def get_events_df(connection, start, end):
    """Return joined occurrences starting within [start, end), indexed by event ID."""
    return pd.read_sql(EVENTS_IN_RANGE_SQL, connection, index_col=['id'],
                       params=(to_db_text(start), to_db_text(end)))


def get_event_row(connection, event_id):
    """Return one joined dictionary, or None when the event does not exist."""
    row = connection.execute(EVENT_BY_ID_SQL, (event_id,)).fetchone()
    return dict(row) if row is not None else None


def get_event_date_range(connection):
    """Return the earliest/latest occurrence dates, or (None, None)."""
    row = connection.execute('SELECT MIN(start_time),MAX(start_time) FROM events').fetchone()
    if row[0] is None:
        return None, None
    return from_db_text(row[0]).date(), from_db_text(row[1]).date()


def get_categories_df(connection):
    """Return bundles joined to their directions in taxonomy order."""
    return pd.read_sql('''SELECT b.id,b.key AS bundle_key,b.name AS bundle_name,
        d.key AS direction_key,d.name AS direction_name FROM bundles b
        JOIN directions d ON d.id=b.direction_id ORDER BY d.sort_order,b.sort_order
    ''', connection, index_col=['id'])


def get_source_counts_df(connection):
    """Return stored source totals for the data-status panel."""
    return pd.read_sql('''SELECT MIN(s.id) AS id,s.source,COUNT(DISTINCT s.id) AS series,
        COUNT(e.id) AS occurrences FROM series s LEFT JOIN events e ON e.series_id=s.id
        GROUP BY s.source''', connection, index_col=['id'])


def delete_past_unconfirmed_events(connection, now=None):
    """Delete ended occurrences only when no history or invitation refers to them."""
    with connection:
        cursor = connection.execute('''DELETE FROM events WHERE end_time<?
            AND NOT EXISTS (SELECT 1 FROM interactions WHERE event_id=events.id)
            AND NOT EXISTS (SELECT 1 FROM invitations WHERE event_id=events.id)
        ''', (to_db_text(config.local_now(now)),))
    return cursor.rowcount


def log_import(connection, source, origin, n_series=0, n_events=0,
               outcome='ok', message='', now=None):
    """Append one sanitized report for one complete source import run."""
    with connection:
        connection.execute('''INSERT INTO import_log
            (source,started_at,origin,n_series,n_events,outcome,message) VALUES (?,?,?,?,?,?,?)
        ''', (source, to_db_text(config.local_now(now)), origin,
              n_series, n_events, outcome, message))


def get_import_log_df(connection):
    """Return source-run reports, newest first."""
    return pd.read_sql('SELECT * FROM import_log ORDER BY id DESC', connection, index_col=['id'])


def get_calendar_confirmations(connection, start, end):
    """Read current-user confirmations overlapping the week without storing private entries."""
    user_id = get_setting(connection, 'current_user_id')
    return pd.read_sql(CONFIRMED_EVENTS_SQL, connection, index_col=['id'],
                       params=(user_id, to_db_text(end), to_db_text(start)))
